def balanced(text):
    pair = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pair[ch]:
                return False
    return not stack

assert balanced("([])") and balanced("()[]")
assert not balanced("([)]") and not balanced("(((")

stack = []
for value in (6, 1, 8, 3):
    stack.append(value)
popped = [stack.pop(), stack.pop()]
assert popped == [3, 8] and sum(popped) == 11

